colossal_kraken.source:
export const envelope = [48, 42, 48];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;

  // Block ID Palette Mapping
  const ID_MAP = [
    null,
    "minecraft:dark_prismarine",
    "minecraft:prismarine",
    "minecraft:prismarine_bricks",
    "minecraft:polished_blackstone",
    "minecraft:deepslate_tiles",
    "minecraft:crying_obsidian",
    "minecraft:sea_lantern",
    "minecraft:ochre_froglight",
    "minecraft:shroomlight",
    "minecraft:warped_wart_block",
    "minecraft:cyan_terracotta",
    "minecraft:bone_block[axis=y]",
    "minecraft:calcite",
    "minecraft:magma_block",
    "minecraft:blackstone",
    "minecraft:prismarine_wall",
    "minecraft:deepslate_tile_wall",
    "minecraft:end_rod[facing=up]",
    "minecraft:end_rod[facing=down]",
    "minecraft:end_rod[facing=north]",
    "minecraft:end_rod[facing=south]",
    "minecraft:end_rod[facing=east]",
    "minecraft:end_rod[facing=west]",
    "minecraft:quartz_stairs[facing=south,half=top]",
    "minecraft:quartz_stairs[facing=north,half=bottom]",
    "minecraft:dark_prismarine_stairs[facing=north,half=bottom]",
    "minecraft:dark_prismarine_stairs[facing=south,half=bottom]",
    "minecraft:dark_prismarine_stairs[facing=east,half=bottom]",
    "minecraft:dark_prismarine_stairs[facing=west,half=bottom]",
    "minecraft:dark_prismarine_slab[type=bottom]",
    "minecraft:verdant_froglight"
  ];

  const grid = new Uint8Array(W * H * D);

  function setVoxel(x, y, z, id) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x + y * W + z * W * H] = id;
    }
  }

  function getVoxel(x, y, z) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x + y * W + z * W * H];
    }
    return 0;
  }

  // Catmull-Rom Spline Interpolation
  function catmullRom(p0, p1, p2, p3, t) {
    const t2 = t * t;
    const t3 = t2 * t;
    return [
      0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3),
      0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3),
      0.5 * ((2 * p1[2]) + (-p0[2] + p2[2]) * t + (2 * p0[2] - 5 * p1[2] + 4 * p2[2] - p3[2]) * t2 + (-p0[2] + 3 * p1[2] - 3 * p2[2] + p3[2]) * t3)
    ];
  }

  function evaluateSpline(knots, t) {
    const numSegments = knots.length - 1;
    const p = Math.max(0, Math.min(1, t)) * numSegments;
    const i = Math.min(Math.floor(p), numSegments - 1);
    const localT = p - i;
    const p0 = knots[Math.max(i - 1, 0)];
    const p1 = knots[i];
    const p2 = knots[Math.min(i + 1, knots.length - 1)];
    const p3 = knots[Math.min(i + 2, knots.length - 1)];
    return catmullRom(p0, p1, p2, p3, localT);
  }

  // Rasterize a sphere into the grid
  function stampSphere(cx, cy, cz, r, getBlockId) {
    const rCeil = Math.ceil(r);
    const r2 = r * r;
    const minX = Math.max(0, Math.floor(cx - rCeil));
    const maxX = Math.min(W - 1, Math.ceil(cx + rCeil));
    const minY = Math.max(0, Math.floor(cy - rCeil));
    const maxY = Math.min(H - 1, Math.ceil(cy + rCeil));
    const minZ = Math.max(0, Math.floor(cz - rCeil));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rCeil));

    for (let x = minX; x <= maxX; x++) {
      const dx = x - cx;
      for (let y = minY; y <= maxY; y++) {
        const dy = y - cy;
        for (let z = minZ; z <= maxZ; z++) {
          const dz = z - cz;
          const d2 = dx * dx + dy * dy + dz * dz;
          if (d2 <= r2) {
            const id = getBlockId(x, y, z, Math.sqrt(d2), dx, dy, dz);
            if (id !== 0) {
              setVoxel(x, y, z, id);
            }
          }
        }
      }
    }
  }

  // --- 1. LEVIATHAN CORE BODY & MANTLE ---
  // Torso base
  for (let x = 12; x <= 36; x++) {
    for (let y = 4; y <= 24; y++) {
      for (let z = 14; z <= 36; z++) {
        const dx = (x - 24) / 10.5;
        const dy = (y - 14) / 9.5;
        const dz = (z - 25) / 11.0;
        const d = dx * dx + dy * dy + dz * dz;
        if (d <= 1.0) {
          let id = 1; // Dark prismarine
          if (y < 12 && z < 22) {
            id = (x + z) % 2 === 0 ? 2 : 11; // Prismarine & Cyan terracotta underbelly
          } else if (y > 18) {
            id = (x + y + z) % 7 === 0 ? 6 : 4; // Crying obsidian veins & Polished blackstone
          } else if ((x ^ y ^ z) % 9 === 0) {
            id = 5; // Deepslate tiles
          }
          setVoxel(x, y, z, id);
        }
      }
    }
  }

  // Cephalopod Mantle Dome (rearing up and backward)
  for (let x = 15; x <= 33; x++) {
    for (let y = 18; y <= 33; y++) {
      for (let z = 20; z <= 38; z++) {
        const dx = (x - 24) / 8.0;
        const dy = (y - 24) / 9.0;
        const dz = (z - 29) / 8.5;
        const d = dx * dx + dy * dy + dz * dz;
        if (d <= 1.0) {
          let id = 1;
          if (y > 28) {
            id = Math.abs(x - 24) <= 1 ? 6 : 4; // Crested spine
          } else if ((x + z) % 5 === 0) {
            id = 5;
          }
          setVoxel(x, y, z, id);
        }
      }
    }
  }

  // Upper Head / Brow (thrusting forward North)
  for (let x = 16; x <= 32; x++) {
    for (let y = 17; y <= 26; y++) {
      for (let z = 10; z <= 22; z++) {
        const dx = (x - 24) / 7.5;
        const dy = (y - 21) / 5.0;
        const dz = (z - 16) / 6.0;
        const d = dx * dx + dy * dy + dz * dz;
        if (d <= 1.0) {
          let id = 1;
          if (y >= 23 && Math.abs(x - 24) <= 2) {
            id = 6; // Crying obsidian brow ridge
          } else if (z <= 12) {
            id = 4;
          }
          setVoxel(x, y, z, id);
        }
      }
    }
  }

  // Lower Jaw (protruding forward beneath maw)
  for (let x = 17; x <= 31; x++) {
    for (let y = 9; y <= 16; y++) {
      for (let z = 9; z <= 20; z++) {
        const dx = (x - 24) / 6.5;
        const dy = (y - 12.5) / 3.5;
        const dz = (z - 14.5) / 5.5;
        const d = dx * dx + dy * dy + dz * dz;
        if (d <= 1.0) {
          let id = 1;
          if (y <= 11) {
            id = (x + z) % 2 === 0 ? 2 : 11;
          } else {
            id = 4;
          }
          setVoxel(x, y, z, id);
        }
      }
    }
  }

  // --- 2. GAPING MAW CAVITY & RAZOR TEETH ---
  // Carve the open mouth cavity
  for (let x = 18; x <= 30; x++) {
    for (let y = 13; y <= 21; y++) {
      for (let z = 9; z <= 23; z++) {
        const dx = (x - 24) / 5.2;
        const dy = (y - 17.0) / 3.8;
        const dz = (z - 15.0) / 7.0;
        if (dx * dx + dy * dy + dz * dz < 0.95) {
          setVoxel(x, y, z, 0); // Open air inside mouth
        }
      }
    }
  }

  // Glowing gullet / throat depths
  for (let x = 22; x <= 26; x++) {
    for (let y = 15; y <= 19; y++) {
      for (let z = 20; z <= 24; z++) {
        const dx = (x - 24) / 2.0;
        const dy = (y - 17) / 2.0;
        const dz = (z - 22) / 2.0;
        if (dx * dx + dy * dy + dz * dz <= 1.0) {
          const mat = (x + y + z) % 3 === 0 ? 14 : (y === 17 ? 9 : 6); // Magma, Shroomlight, Crying Obsidian
          setVoxel(x, y, z, mat);
        }
      }
    }
  }

  // Upper Jaw Razor Teeth (pointing down)
  const upperTeethX = [19, 21, 23, 25, 27, 29];
  for (const tx of upperTeethX) {
    const tz = 11 + Math.abs(tx - 24) * 0.5;
    setVoxel(tx, 20, tz, 12); // Bone block
    setVoxel(tx, 19, tz, 13); // Calcite
    setVoxel(tx, 18, tz, 24); // Quartz stairs (down)
  }
  // Primary giant upper tusks
  setVoxel(18, 19, 11, 12);
  setVoxel(18, 18, 10, 13);
  setVoxel(18, 17, 10, 19); // End rod down
  setVoxel(30, 19, 11, 12);
  setVoxel(30, 18, 10, 13);
  setVoxel(30, 17, 10, 19); // End rod down

  // Lower Jaw Razor Teeth (pointing up)
  const lowerTeethX = [19, 21, 23, 25, 27, 29];
  for (const tx of lowerTeethX) {
    const tz = 11 + Math.abs(tx - 24) * 0.5;
    setVoxel(tx, 14, tz, 12); // Bone block
    setVoxel(tx, 15, tz, 13); // Calcite
    setVoxel(tx, 16, tz, 25); // Quartz stairs (up)
  }
  // Primary giant lower tusks
  setVoxel(18, 14, 10, 12);
  setVoxel(18, 15, 9, 13);
  setVoxel(18, 16, 9, 18); // End rod up
  setVoxel(30, 14, 10, 12);
  setVoxel(30, 15, 9, 13);
  setVoxel(30, 16, 9, 18); // End rod up

  // Inner concentric ring of teeth
  const innerTeeth = [
    [21, 19, 16], [24, 20, 16], [27, 19, 16],
    [21, 15, 16], [24, 14, 16], [27, 15, 16],
    [20, 17, 16], [28, 17, 16]
  ];
  for (const [ix, iy, iz] of innerTeeth) {
    setVoxel(ix, iy, iz, 13);
  }

  // --- 3. MULTI-EYES OF THE LEVIATHAN ---
  // Left Primary Eye
  for (let dy = -1; dy <= 1; dy++) {
    for (let dz = -1; dz <= 1; dz++) {
      setVoxel(15, 21 + dy, 15 + dz, 6); // Crying obsidian socket
    }
  }
  setVoxel(15, 21, 15, 8); // Ochre froglight eye center
  setVoxel(14, 21, 15, 4); // Blackstone pupil

  // Right Primary Eye
  for (let dy = -1; dy <= 1; dy++) {
    for (let dz = -1; dz <= 1; dz++) {
      setVoxel(33, 21 + dy, 15 + dz, 6); // Crying obsidian socket
    }
  }
  setVoxel(33, 21, 15, 8); // Ochre froglight eye center
  setVoxel(34, 21, 15, 4); // Blackstone pupil

  // Forehead Cyclopean Eye
  setVoxel(24, 26, 12, 31); // Verdant froglight
  setVoxel(23, 26, 12, 6);
  setVoxel(25, 26, 12, 6);
  setVoxel(24, 27, 12, 6);
  setVoxel(24, 25, 12, 6);

  // Auxiliary Stalk & Temple Eyes
  const auxEyes = [
    [19, 25, 13, 7],
    [29, 25, 13, 7],
    [13, 17, 18, 8],
    [35, 17, 18, 8],
    [17, 24, 14, 7],
    [31, 24, 14, 7],
    [21, 22, 11, 8],
    [27, 22, 11, 8]
  ];
  for (const [ex, ey, ez, mat] of auxEyes) {
    setVoxel(ex, ey, ez, mat);
  }

  // --- 4. BIOLUMINESCENT DORSAL SPINES & CRESTS ---
  // Towering Dorsal Spine Arch along Mantle
  for (let z = 18; z <= 38; z++) {
    const progress = (z - 18) / 20.0;
    const archH = 22 + Math.sin(progress * Math.PI) * 16.0; // Peaks at y=38!
    const peakY = Math.floor(archH);
    for (let y = 22; y <= peakY; y++) {
      setVoxel(24, y, z, 1);
    }
    // Bioluminescent crest cap & spine spikes
    if (peakY < H - 1) {
      setVoxel(24, peakY, z, (z % 3 === 0) ? 7 : 6); // Sea lantern / Crying obsidian
      if (peakY + 1 < H && z % 2 === 0) {
        setVoxel(24, peakY + 1, z, 16); // Prismarine wall spike
      }
    }
    // Flanking ridges
    setVoxel(23, peakY - 1, z, 28); // Stairs East
    setVoxel(25, peakY - 1, z, 29); // Stairs West
  }

  // --- 5. TENTACLE SPLINES DEFINITION & GENERATION ---
  const tentacles = [
    // 1: Front Left Towering Whip (Crashes North-West towards quays)
    {
      knots: [
        [18, 5, 20], [14, 12, 16], [9, 23, 12],
        [5, 34, 8], [3, 39, 4], [2, 30, 2], [4, 18, 1]
      ],
      rStart: 4.2, rEnd: 0.8, suckerStep: 22
    },
    // 2: Front Right Towering Whip (Crashes North-East towards quays)
    {
      knots: [
        [30, 5, 20], [34, 12, 16], [39, 23, 12],
        [43, 34, 8], [45, 39, 4], [46, 30, 2], [44, 18, 1]
      ],
      rStart: 4.2, rEnd: 0.8, suckerStep: 22
    },
    // 3: Front Center-Left Low Harbor Sweeper (Reaches straight North)
    {
      knots: [
        [20, 5, 17], [17, 8, 12], [13, 11, 7],
        [9, 9, 3], [8, 5, 1], [12, 3, 0]
      ],
      rStart: 3.5, rEnd: 0.7, suckerStep: 18
    },
    // 4: Front Center-Right Low Harbor Sweeper (Reaches straight North)
    {
      knots: [
        [28, 5, 17], [31, 8, 12], [35, 11, 7],
        [39, 9, 3], [40, 5, 1], [36, 3, 0]
      ],
      rStart: 3.5, rEnd: 0.7, suckerStep: 18
    },
    // 5: Left Flank High Rearing Coil
    {
      knots: [
        [15, 5, 26], [8, 13, 25], [4, 24, 22],
        [3, 34, 18], [5, 39, 14], [9, 36, 11], [13, 28, 10]
      ],
      rStart: 4.0, rEnd: 0.8, suckerStep: 20
    },
    // 6: Right Flank High Rearing Coil
    {
      knots: [
        [33, 5, 26], [40, 13, 25], [44, 24, 22],
        [45, 34, 18], [43, 39, 14], [39, 36, 11], [35, 28, 10]
      ],
      rStart: 4.0, rEnd: 0.8, suckerStep: 20
    },
    // 7: Rear Left Skyward Whip (South-West)
    {
      knots: [
        [17, 5, 32], [11, 14, 36], [6, 25, 40],
        [4, 35, 43], [7, 39, 45], [12, 36, 46], [16, 28, 44]
      ],
      rStart: 3.8, rEnd: 0.8, suckerStep: 20
    },
    // 8: Rear Right Skyward Whip (South-East)
    {
      knots: [
        [31, 5, 32], [37, 14, 36], [42, 25, 40],
        [44, 35, 43], [41, 39, 45], [36, 36, 46], [32, 28, 44]
      ],
      rStart: 3.8, rEnd: 0.8, suckerStep: 20
    },
    // 9: Dorsal Mantle Crown Whip
    {
      knots: [
        [24, 10, 36], [24, 22, 42], [24, 33, 44],
        [24, 39, 41], [24, 40, 35], [24, 36, 29], [24, 29, 25]
      ],
      rStart: 3.5, rEnd: 0.7, suckerStep: 20
    },
    // 10: Left Grasping Mandible
    {
      knots: [
        [17, 16, 14], [14, 15, 11], [15, 14, 7], [19, 13, 5], [22, 14, 6]
      ],
      rStart: 1.8, rEnd: 0.6, suckerStep: 14
    },
    // 11: Right Grasping Mandible
    {
      knots: [
        [31, 16, 14], [34, 15, 11], [33, 14, 7], [29, 13, 5], [26, 14, 6]
      ],
      rStart: 1.8, rEnd: 0.6, suckerStep: 14
    }
  ];

  // Rasterize all tentacles with organic skin, glowing suckers, and dorsal spines
  for (const tentacle of tentacles) {
    const steps = 120;
    for (let s = 0; s <= steps; s++) {
      const u = s / steps;
      const P = evaluateSpline(tentacle.knots, u);
      const r = tentacle.rStart * (1 - u) + tentacle.rEnd * u;

      // Calculate direction vectors
      const dxCore = P[0] - 24;
      const dyCore = P[1] - 15;
      const dzCore = P[2] - 25;
      const distCore = Math.hypot(dxCore, dyCore, dzCore) || 1;
      const nx = dxCore / distCore;
      const ny = dyCore / distCore;
      const nz = dzCore / distCore;

      stampSphere(P[0], P[1], P[2], r, (vx, vy, vz, dist, dx, dy, dz) => {
        const dotDorsal = (dx * nx + dy * ny + dz * nz) / (dist + 0.001);
        const dotVentral = -dotDorsal;

        // Ventral / Inner side: Glowing suction cups
        if (dotVentral > 0.42 && dist > r - 0.95) {
          const suckerIdx = Math.floor(u * tentacle.suckerStep);
          if (suckerIdx % 2 === 0) {
            return (dist > r - 0.45) ? 7 : 3; // Sea lantern rimmed with Prismarine bricks
          }
          return 2; // Prismarine
        }

        // Dorsal / Outer side: Hard dark carapace with bio-luminescent scales
        if (dotDorsal > 0.38 && dist > r - 0.9) {
          if ((vx + vy + vz) % 6 === 0) {
            return 6; // Crying obsidian vein
          }
          return (vx ^ vz) % 3 === 0 ? 5 : 1; // Deepslate tiles & Dark prismarine
        }

        // Internal tentacle muscle
        return 1; // Dark prismarine core
      });

      // Place Spines along the dorsal ridge at regular intervals
      if (s % 12 === 0 && u > 0.15 && u < 0.92) {
        const spinePos = [
          P[0] + nx * (r + 0.9),
          P[1] + ny * (r + 0.9),
          P[2] + nz * (r + 0.9)
        ];
        const spX = Math.round(spinePos[0]);
        const spY = Math.round(spinePos[1]);
        const spZ = Math.round(spinePos[2]);

        if (spX >= 0 && spX < W && spY >= 0 && spY < H && spZ >= 0 && spZ < D) {
          if (getVoxel(spX, spY, spZ) === 0) {
            let spineMat = 16; // Prismarine wall
            if (ny > 0.5) spineMat = 18; // End rod up
            else if (nz < -0.5) spineMat = 20; // End rod north
            else if (nz > 0.5) spineMat = 21; // End rod south
            setVoxel(spX, spY, spZ, spineMat);
          }
        }
      }
    }
  }

  // --- 6. SUBMERGED BASE & SEABED GROUND CONFORMITY ---
  // Submerged anchoring reef disk at base
  for (let x = 8; x <= 40; x++) {
    for (let z = 10; z <= 42; z++) {
      const dx = (x - 24) / 13.0;
      const dz = (z - 26) / 14.0;
      const dist2 = dx * dx + dz * dz;
      if (dist2 <= 1.0) {
        const h = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(H - 1, Math.round(seatY + h)));
        const topY = Math.max(groundY, Math.round(seatY + 1 + (1 - dist2) * 3.5));
        for (let y = groundY; y <= topY; y++) {
          if (getVoxel(x, y, z) === 0) {
            const mat = dist2 > 0.8 ? 1 : ((x + y + z) % 5 === 0 ? 6 : 1);
            setVoxel(x, y, z, mat);
          }
        }
      }
    }
  }

  // Extend all occupied ground columns downward to conform to the local seabed
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let lowestY = -1;
      for (let y = 0; y < H; y++) {
        if (getVoxel(x, y, z) !== 0) {
          lowestY = y;
          break;
        }
      }
      if (lowestY !== -1 && lowestY <= 14) {
        const h = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(H - 1, Math.round(seatY + h)));
        for (let y = lowestY - 1; y >= groundY; y--) {
          const mat = (x + y + z) % 5 === 0 ? 6 : ((x ^ z) & 1 ? 1 : 3);
          setVoxel(x, y, z, mat);
        }
      }
    }
  }

  // --- 7. EMIT BLOCKS DETERMINISTICALLY ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const id = grid[x + y * W + z * W * H];
        if (id > 0 && id < ID_MAP.length) {
          api.set(x, y, z, ID_MAP[id]);
        }
      }
    }
  }

  return {
    name: "colossal_kraken",
    seatY: seatY,
    anchors: {
      front: [24, 16, 0],
      maw: [24, 17, 12],
      eye_left: [15, 21, 15],
      eye_right: [33, 21, 15],
      crest: [24, 38, 26]
    }
  };
}

hellenist_colossus_statue.source:
export const envelope = [25, 56, 25];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const seatY = 8;
  const cx = 12;
  const cz = 12;

  // Grid buffer to ensure deterministic writing and strict envelope containment
  const grid = new Map();

  function set(x, y, z, block) {
    if (x < 0 || x >= sizeX || y < 0 || y >= sizeY || z < 0 || z >= sizeZ) {
      return;
    }
    const key = (x << 16) | (y << 8) | z;
    grid.set(key, { x, y, z, block });
  }

  function fillBox(x0, y0, z0, x1, y1, z1, block) {
    const minX = Math.min(x0, x1), maxX = Math.max(x0, x1);
    const minY = Math.min(y0, y1), maxY = Math.max(y0, y1);
    const minZ = Math.min(z0, z1), maxZ = Math.max(z0, z1);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          set(x, y, z, block);
        }
      }
    }
  }

  // Theme palettes with robust Hellenic classical fallbacks
  const stonePrimary = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:quartz_pillar";
  const revetment = api.theme?.ground?.revetment || "minecraft:stone_bricks";
  const plinthBlock = api.theme?.ground?.plinth || "minecraft:polished_diorite";

  // Colossus Bronze, Quartz, Prismarine, and Gold materials
  const C_BRONZE = "minecraft:cut_copper";
  const C_BRONZE_DARK = "minecraft:weathered_cut_copper";
  const C_BRONZE_LIGHT = "minecraft:copper_block";
  const C_OXIDIZED = "minecraft:oxidized_cut_copper";
  const C_GOLD = "minecraft:gold_block";
  const C_RAW_GOLD = "minecraft:raw_gold_block";
  const C_MARBLE = "minecraft:smooth_quartz";
  const C_CLOAK = "minecraft:dark_prismarine";
  const C_CLOAK_BRIGHT = "minecraft:prismarine_bricks";
  const C_CLOAK_TRIM = "minecraft:prismarine";
  const C_LANTERN = "minecraft:sea_lantern";

  function inOctagon(x, z, r) {
    const dx = Math.abs(x - cx);
    const dz = Math.abs(z - cz);
    return dx <= r && dz <= r && (dx + dz) <= Math.floor(r * 1.45 + 0.5);
  }

  function getStairFacing(x, z) {
    const dx = x - cx;
    const dz = z - cz;
    if (Math.abs(dz) >= Math.abs(dx)) {
      return dz >= 0 ? "south" : "north";
    } else {
      return dx >= 0 ? "east" : "west";
    }
  }

  // 1. GROUND CONFORMANCE & FOUNDATION SKIRT (Rule 6)
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      if (inOctagon(x, z, 9)) {
        const gh = Math.round(api.heightAt(x, z));
        const groundY = Math.max(0, Math.min(seatY + 3, seatY + gh));

        // Extend foundation down into slopes or seabeds
        if (groundY < seatY) {
          for (let y = groundY; y < seatY; y++) {
            set(x, y, z, revetment);
          }
        }
        // Build foundation up to meet rising ground
        if (groundY > seatY) {
          for (let y = seatY; y <= groundY; y++) {
            set(x, y, z, revetment);
          }
        }
      }
    }
  }

  // 2. MONUMENTAL STEPPED PLINTH (y = 8 to 11)
  // Step 0 (y = 8, r = 9)
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      if (inOctagon(x, z, 9)) {
        if (!inOctagon(x, z, 8)) {
          const facing = getStairFacing(x, z);
          set(x, 8, z, `minecraft:quartz_stairs[facing=${facing},half=bottom,shape=straight]`);
        } else {
          set(x, 8, z, plinthBlock);
        }
      }
    }
  }

  // Step 1 (y = 9, r = 8)
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      if (inOctagon(x, z, 8)) {
        if (!inOctagon(x, z, 7)) {
          const facing = getStairFacing(x, z);
          set(x, 9, z, `minecraft:quartz_stairs[facing=${facing},half=bottom,shape=straight]`);
        } else {
          set(x, 9, z, stonePrimary);
        }
      }
    }
  }

  // Step 2 (y = 10, r = 7)
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      if (inOctagon(x, z, 7)) {
        if (!inOctagon(x, z, 6)) {
          const facing = getStairFacing(x, z);
          set(x, 10, z, `minecraft:quartz_stairs[facing=${facing},half=bottom,shape=straight]`);
        } else {
          set(x, 10, z, stonePrimary);
        }
      }
    }
  }

  // Step 3 / Base Molding (y = 11, r = 6)
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      if (inOctagon(x, z, 6)) {
        if (!inOctagon(x, z, 5)) {
          set(x, 11, z, "minecraft:quartz_slab[type=bottom]");
        } else {
          set(x, 11, z, stonePrimary);
        }
      }
    }
  }

  // 3. PEDESTAL SHAFT & CLASSICAL PANELS (y = 12 to 19, r = 5)
  for (let y = 12; y <= 19; y++) {
    for (let x = 0; x < sizeX; x++) {
      for (let z = 0; z < sizeZ; z++) {
        if (inOctagon(x, z, 5)) {
          const isEdge = !inOctagon(x, z, 4);
          if (isEdge) {
            const dx = Math.abs(x - cx);
            const dz = Math.abs(z - cz);
            // Corner pilasters
            if ((dx >= 4 && dz >= 4) || (dx === 5 && dz === 0) || (dx === 0 && dz === 5)) {
              set(x, y, z, stoneAccent);
            }
            // North face relief panel (facing the invading sea monsters)
            else if (z === cz - 5 && dx <= 2 && y >= 14 && y <= 18) {
              if (dx === 0 && y === 16) {
                set(x, y, z, C_LANTERN);
              } else if (dx === 1) {
                set(x, y, z, C_CLOAK);
              } else {
                set(x, y, z, C_CLOAK_BRIGHT);
              }
            }
            // South face relief panel
            else if (z === cz + 5 && dx <= 2 && y >= 14 && y <= 18) {
              set(x, y, z, dx === 0 && y === 16 ? C_GOLD : C_CLOAK);
            }
            // East / West flank relief panels
            else if ((x === cx + 5 || x === cx - 5) && dz <= 2 && y >= 14 && y <= 18) {
              set(x, y, z, dz === 0 && y === 16 ? C_LANTERN : C_CLOAK_BRIGHT);
            } else {
              set(x, y, z, stonePrimary);
            }
          } else {
            set(x, y, z, stonePrimary);
          }
        }
      }
    }
  }

  // Pedestal Corner Beacons / Hellenic floodlights at y = 19..21
  const cornerCoords = [
    [cx - 5, cz - 5], [cx + 5, cz - 5],
    [cx - 5, cz + 5], [cx + 5, cz + 5]
  ];
  for (const [bx, bz] of cornerCoords) {
    set(bx, 19, bz, C_BRONZE);
    set(bx, 20, bz, C_LANTERN);
    set(bx, 21, bz, "minecraft:weathered_cut_copper_slab[type=bottom]");
  }

  // 4. PEDESTAL CORNICE & MOUNTING TERRACE (y = 20 to 21)
  // y = 20 (Cornice flaring outward)
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      if (inOctagon(x, z, 5)) {
        if (!inOctagon(x, z, 4)) {
          const facing = getStairFacing(x, z);
          set(x, 20, z, `minecraft:quartz_stairs[facing=${facing},half=top,shape=straight]`);
        } else {
          set(x, 20, z, stonePrimary);
        }
      }
    }
  }

  // y = 21 (Pedestal terrace & bronze mounting ring)
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      if (inOctagon(x, z, 5)) {
        if (!inOctagon(x, z, 4)) {
          set(x, 21, z, "minecraft:quartz_slab[type=bottom]");
        } else {
          const dist = Math.hypot(x - cx, z - cz);
          if (dist >= 2.2 && dist <= 3.8) {
            set(x, 21, z, C_BRONZE);
          } else {
            set(x, 21, z, stonePrimary);
          }
        }
      }
    }
  }

  // 5. CRASHING WAVE & LEVIATHAN CREST (under Poseidon's left foot)
  fillBox(9, 21, 8, 12, 21, 11, C_CLOAK);
  fillBox(9, 22, 8, 12, 22, 10, C_CLOAK_BRIGHT);
  set(10, 22, 9, C_LANTERN);
  set(11, 22, 9, C_CLOAK);
  set(8, 22, 9, "minecraft:prismarine_slab[type=bottom]");
  set(9, 22, 7, "minecraft:prismarine_slab[type=bottom]");

  fillBox(10, 23, 9, 11, 23, 10, C_CLOAK_TRIM);
  set(10, 23, 8, C_LANTERN);
  set(11, 23, 8, C_CLOAK_BRIGHT);
  set(10, 24, 8, "minecraft:prismarine_wall");

  // 6. BILLOWING SEA-CLOAK SPINE (Structural back anchor)
  fillBox(12, 21, 15, 16, 21, 17, C_CLOAK);
  fillBox(13, 22, 15, 16, 22, 17, C_CLOAK_BRIGHT);
  fillBox(13, 23, 15, 16, 23, 16, C_CLOAK);
  fillBox(13, 24, 15, 16, 24, 16, C_CLOAK_TRIM);

  for (let y = 25; y <= 33; y++) {
    const mat = (y % 2 === 0) ? C_CLOAK : C_CLOAK_BRIGHT;
    fillBox(11, y, 14, 15, y, 16, mat);
    if (y >= 28) {
      fillBox(10, y, 13, 11, y, 15, C_CLOAK);
    }
  }

  // 7. POSEIDON'S LEGS (Heroic combat stance)
  // Right Leg (Planted back firmly on pedestal)
  fillBox(14, 22, 14, 15, 22, 16, C_BRONZE);
  fillBox(14, 23, 14, 15, 23, 15, C_BRONZE);
  fillBox(14, 24, 14, 15, 24, 15, C_BRONZE_LIGHT);
  fillBox(14, 25, 14, 15, 25, 15, C_BRONZE);
  set(13, 25, 14, C_BRONZE);
  fillBox(14, 26, 14, 15, 26, 15, C_BRONZE_LIGHT);
  fillBox(14, 27, 13, 15, 27, 14, C_BRONZE);
  fillBox(13, 28, 13, 15, 28, 14, C_BRONZE_LIGHT);
  fillBox(13, 29, 13, 15, 29, 14, C_BRONZE);
  fillBox(13, 30, 12, 15, 30, 14, C_BRONZE_LIGHT);
  fillBox(12, 31, 12, 15, 31, 14, C_BRONZE);

  // Left Leg (Lunging forward, raised on wave crest)
  fillBox(10, 23, 9, 11, 23, 10, C_BRONZE);
  fillBox(10, 24, 9, 11, 24, 10, C_BRONZE_LIGHT);
  fillBox(10, 25, 9, 11, 25, 10, C_BRONZE);
  set(10, 25, 11, C_BRONZE);
  fillBox(10, 26, 9, 11, 26, 10, C_BRONZE_LIGHT);
  fillBox(10, 27, 9, 11, 27, 10, C_BRONZE);
  fillBox(10, 28, 10, 12, 28, 11, C_BRONZE_LIGHT);
  fillBox(10, 29, 10, 12, 29, 12, C_BRONZE);
  fillBox(10, 30, 11, 12, 30, 13, C_BRONZE_LIGHT);
  fillBox(10, 31, 11, 13, 31, 13, C_BRONZE);

  // 8. PELVIS, WAIST & HEROIC TORSO
  // Pelvis & Girdle (y = 32)
  fillBox(10, 32, 11, 15, 32, 14, C_BRONZE);
  fillBox(11, 32, 11, 14, 32, 11, C_GOLD);

  // Belt / Olympian Cincture (y = 33)
  fillBox(10, 33, 11, 15, 33, 14, C_BRONZE);
  fillBox(10, 33, 11, 15, 33, 11, C_GOLD);
  set(12, 33, 11, C_LANTERN);

  // Abdomen (y = 34)
  fillBox(10, 34, 11, 14, 34, 13, C_BRONZE);
  set(11, 34, 11, C_MARBLE);
  set(13, 34, 11, C_MARBLE);

  // Upper Abdomen (y = 35)
  fillBox(9, 35, 10, 15, 35, 13, C_BRONZE_LIGHT);
  set(11, 35, 10, C_MARBLE);
  set(13, 35, 10, C_MARBLE);

  // Ribcage & Lower Pectorals (y = 36)
  fillBox(9, 36, 10, 15, 36, 13, C_BRONZE);
  fillBox(10, 36, 10, 14, 36, 10, C_BRONZE_LIGHT);

  // Muscular Pectorals (y = 37)
  fillBox(8, 37, 10, 16, 37, 13, C_BRONZE);
  fillBox(9, 37, 10, 11, 37, 10, C_MARBLE);
  fillBox(13, 37, 10, 15, 37, 10, C_MARBLE);
  set(12, 37, 10, C_BRONZE_LIGHT);

  // Upper Chest & Clavicles (y = 38)
  fillBox(8, 38, 10, 16, 38, 13, C_BRONZE_LIGHT);
  fillBox(9, 38, 10, 15, 38, 10, C_MARBLE);

  // Broad Shoulders & Trapezius (y = 39)
  fillBox(7, 39, 10, 17, 39, 13, C_BRONZE);
  fillBox(10, 39, 10, 14, 39, 12, C_BRONZE_LIGHT);

  // Cloak wrapping around left shoulder (y = 34 to 42)
  fillBox(8, 34, 13, 10, 37, 15, C_CLOAK);
  fillBox(8, 38, 12, 10, 41, 14, C_CLOAK_BRIGHT);
  fillBox(8, 41, 11, 10, 42, 13, C_CLOAK);

  // 9. ARMS & HANDS
  // Left Arm (Outstretched seaward -Z in commanding gesture)
  fillBox(8, 38, 8, 9, 39, 10, C_BRONZE_LIGHT);
  fillBox(8, 37, 5, 9, 38, 7, C_BRONZE);
  set(8, 37, 4, C_LANTERN);
  set(9, 37, 4, C_BRONZE_LIGHT);
  set(8, 38, 4, C_BRONZE);
  set(8, 37, 3, "minecraft:end_rod[facing=north]");

  // Right Arm (Raised high clutching the trident)
  fillBox(16, 40, 11, 17, 41, 13, C_BRONZE_LIGHT);
  fillBox(16, 42, 11, 17, 43, 12, C_BRONZE);
  fillBox(15, 44, 11, 16, 45, 12, C_BRONZE_LIGHT);
  fillBox(14, 46, 11, 16, 46, 12, C_BRONZE);
  set(15, 46, 11, C_GOLD);

  // 10. NECK, BEARDED HEAD & OLYMPIAN CROWN
  // Neck (y = 40 to 41)
  fillBox(11, 40, 11, 13, 41, 12, C_BRONZE_LIGHT);

  // Classical Flowing Beard (y = 41 to 43)
  fillBox(11, 41, 9, 13, 41, 10, C_BRONZE_DARK);
  fillBox(10, 42, 9, 14, 42, 10, C_OXIDIZED);
  fillBox(11, 43, 9, 13, 43, 9, C_BRONZE_DARK);

  // Head Mass (y = 42 to 45)
  fillBox(10, 42, 10, 14, 45, 13, C_BRONZE);

  // Facial features looking north over the bay
  fillBox(11, 43, 9, 13, 43, 9, C_MARBLE);
  set(11, 44, 9, C_LANTERN); // Left eye
  set(13, 44, 9, C_LANTERN); // Right eye
  set(12, 44, 8, C_BRONZE_LIGHT); // Nose bridge
  set(12, 44, 9, C_MARBLE);
  fillBox(11, 45, 9, 13, 45, 9, C_BRONZE_LIGHT); // Brow

  // Hair mane (y = 43 to 45)
  fillBox(10, 43, 12, 14, 45, 13, C_BRONZE_DARK);
  fillBox(9, 44, 10, 9, 45, 12, C_OXIDIZED);
  fillBox(15, 44, 10, 15, 45, 12, C_OXIDIZED);

  // Radiant Diadem / Crown (y = 46 to 47)
  fillBox(10, 46, 9, 14, 46, 13, C_GOLD);
  set(12, 46, 9, C_LANTERN);
  set(12, 47, 9, "minecraft:lightning_rod[facing=up]");
  set(10, 47, 11, "minecraft:lightning_rod[facing=up]");
  set(14, 47, 11, "minecraft:lightning_rod[facing=up]");
  set(12, 47, 13, "minecraft:lightning_rod[facing=up]");

  // 11. THE MONUMENTAL TRIDENT
  // Shaft (y = 26 to 46, centered at x = 15, z = 11)
  for (let y = 26; y <= 46; y++) {
    const shaftMat = (y % 4 === 0) ? C_LANTERN : (y % 2 === 0) ? C_GOLD : C_RAW_GOLD;
    set(15, y, 11, shaftMat);
  }
  // Stability bracket into hip
  set(15, 32, 12, C_GOLD);
  set(15, 33, 12, C_BRONZE);

  // Trident Head Junction & Crossbar (y = 47 to 48)
  fillBox(12, 47, 11, 18, 47, 11, C_GOLD);
  set(15, 47, 11, C_LANTERN);
  set(13, 47, 11, C_RAW_GOLD);
  set(17, 47, 11, C_RAW_GOLD);
  set(12, 47, 11, "minecraft:cut_copper_stairs[facing=east,half=bottom,shape=straight]");
  set(18, 47, 11, "minecraft:cut_copper_stairs[facing=west,half=bottom,shape=straight]");

  fillBox(12, 48, 11, 18, 48, 11, C_GOLD);
  set(13, 48, 11, C_LANTERN);
  set(17, 48, 11, C_LANTERN);

  // Trident Three Prongs (y = 49 to 55)
  // Central Great Prong (x = 15, z = 11)
  set(15, 49, 11, C_GOLD);
  set(15, 50, 11, C_LANTERN);
  set(15, 51, 11, C_GOLD);
  set(15, 52, 11, C_RAW_GOLD);
  set(15, 53, 11, C_GOLD);
  set(15, 54, 11, C_LANTERN);
  set(15, 55, 11, "minecraft:lightning_rod[facing=up]");

  // West Flank Prong (x = 12, z = 11)
  set(12, 49, 11, C_GOLD);
  set(12, 50, 11, C_GOLD);
  set(11, 50, 11, "minecraft:cut_copper_stairs[facing=west,half=top,shape=straight]");
  set(12, 51, 11, C_LANTERN);
  set(12, 52, 11, C_GOLD);
  set(12, 53, 11, C_GOLD);
  set(12, 54, 11, "minecraft:lightning_rod[facing=up]");

  // East Flank Prong (x = 18, z = 11)
  set(18, 49, 11, C_GOLD);
  set(18, 50, 11, C_GOLD);
  set(19, 50, 11, "minecraft:cut_copper_stairs[facing=east,half=top,shape=straight]");
  set(18, 51, 11, C_LANTERN);
  set(18, 52, 11, C_GOLD);
  set(18, 53, 11, C_GOLD);
  set(18, 54, 11, "minecraft:lightning_rod[facing=up]");

  // Deterministic flush to API in strict coordinate order
  const sortedBlocks = Array.from(grid.values()).sort((a, b) => {
    if (a.y !== b.y) return a.y - b.y;
    if (a.z !== b.z) return a.z - b.z;
    return a.x - b.x;
  });

  for (const b of sortedBlocks) {
    api.set(b.x, b.y, b.z, b.block);
  }

  return {
    name: "Hellenist Colossus of Poseidon",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0],
      pedestal: [cx, seatY + 13, cz],
      trident_tip: [15, 55, 11]
    }
  };
}

