export const envelope = [14, 32, 14];

export default function build(api) {
  const [W, H, D] = envelope;
  const seatY = 6;
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  const setVoxel = (x, y, z, block) => {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid[ix][iy][iz] = block;
    }
  };

  const getVoxel = (x, y, z) => {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      return grid[ix][iy][iz];
    }
    return null;
  };

  // Vector arithmetic helpers
  const vAdd = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
  const vSub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
  const vScale = (a, s) => [a[0] * s, a[1] * s, a[2] * s];
  const vDot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  const vCross = (a, b) => [
    a[1] * b[2] - a[2] * b[1],
    a[2] * b[0] - a[0] * b[2],
    a[0] * b[1] - a[1] * b[0]
  ];
  const vLen = (a) => Math.sqrt(vDot(a, a));
  const vNorm = (a) => {
    const len = vLen(a);
    return len > 1e-6 ? [a[0] / len, a[1] / len, a[2] / len] : [0, 1, 0];
  };

  // Bezier curve evaluation
  const bezier = (p0, p1, p2, p3, t) => {
    const mt = 1 - t;
    const mt2 = mt * mt;
    const mt3 = mt2 * mt;
    const t2 = t * t;
    const t3 = t2 * t;
    return [
      mt3 * p0[0] + 3 * mt2 * t * p1[0] + 3 * mt * t2 * p2[0] + t3 * p3[0],
      mt3 * p0[1] + 3 * mt2 * t * p1[1] + 3 * mt * t2 * p2[1] + t3 * p3[1],
      mt3 * p0[2] + 3 * mt2 * t * p1[2] + 3 * mt * t2 * p2[2] + t3 * p3[2]
    ];
  };

  const bezierD1 = (p0, p1, p2, p3, t) => {
    const mt = 1 - t;
    const mt2 = mt * mt;
    const t2 = t * t;
    return [
      3 * mt2 * (p1[0] - p0[0]) + 6 * mt * t * (p2[0] - p1[0]) + 3 * t2 * (p3[0] - p2[0]),
      3 * mt2 * (p1[1] - p0[1]) + 6 * mt * t * (p2[1] - p1[1]) + 3 * t2 * (p3[1] - p2[1]),
      3 * mt2 * (p1[2] - p0[2]) + 6 * mt * t * (p2[2] - p1[2]) + 3 * t2 * (p3[2] - p2[2])
    ];
  };

  const bezierD2 = (p0, p1, p2, p3, t) => {
    const mt = 1 - t;
    return [
      6 * mt * (p2[0] - 2 * p1[0] + p0[0]) + 6 * t * (p3[0] - 2 * p2[0] + p1[0]),
      6 * mt * (p2[1] - 2 * p1[1] + p0[1]) + 6 * t * (p3[1] - 2 * p2[1] + p1[1]),
      6 * mt * (p2[2] - 2 * p1[2] + p0[2]) + 6 * t * (p3[2] - 2 * p2[2] + p1[2])
    ];
  };

  // Distinct procedural posture archetypes for the 14 instances
  const idx = api.instance.index % 14;
  const p0 = [6.8 + (api.random() - 0.5) * 1.0, seatY, 7.8 + (api.random() - 0.5) * 1.0];

  const presets = [
    { p1: [-1.2, 7.0, -0.4], p2: [-1.0, 22.0, -3.8], p3: [0.6, 14.0, -6.0], r0: 3.3, r1: 0.8 },
    { p1: [1.8, 8.0, 0.4],   p2: [1.4, 23.5, -2.5],  p3: [-1.0, 16.0, -5.5], r0: 3.1, r1: 0.9 },
    { p1: [0.0, 5.5, -1.8],  p2: [1.0, 15.0, -4.6],  p3: [0.0, 8.5, -6.2],  r0: 3.5, r1: 1.1 },
    { p1: [2.2, 7.5, 0.8],   p2: [-1.8, 21.0, -1.8], p3: [0.6, 15.5, -5.0], r0: 3.0, r1: 0.8 },
    { p1: [-0.4, 9.0, 1.2],  p2: [0.0, 24.0, -2.2],  p3: [-0.6, 18.0, -5.8], r0: 3.4, r1: 0.8 },
    { p1: [-1.8, 6.0, -1.0], p2: [-1.4, 18.0, -4.2], p3: [-0.4, 11.0, -6.2], r0: 3.2, r1: 0.9 },
    { p1: [2.4, 7.0, -0.8],  p2: [-1.2, 20.5, -3.2], p3: [-1.8, 14.0, -5.6], r0: 3.1, r1: 0.8 },
    { p1: [0.6, 8.0, -1.2],  p2: [1.8, 21.5, -3.6],  p3: [0.8, 13.0, -5.8], r0: 3.6, r1: 1.0 },
    { p1: [-1.4, 9.5, 0.6],  p2: [1.0, 24.0, -1.8],  p3: [1.4, 19.0, -4.8], r0: 2.9, r1: 0.7 },
    { p1: [1.4, 6.0, -0.6],  p2: [-2.2, 17.5, -3.4], p3: [-0.8, 10.5, -6.0], r0: 3.3, r1: 0.9 },
    { p1: [-1.8, 7.5, 1.2],  p2: [1.8, 22.0, -2.4],  p3: [0.0, 16.5, -5.2], r0: 3.0, r1: 0.8 },
    { p1: [0.0, 5.0, -2.2],  p2: [-0.8, 16.5, -4.8], p3: [-0.4, 9.5, -6.2],  r0: 3.5, r1: 1.0 },
    { p1: [-2.2, 8.0, -0.4], p2: [1.2, 22.5, -2.6],  p3: [-0.4, 17.5, -5.2], r0: 3.2, r1: 0.8 },
    { p1: [0.8, 9.5, 0.4],   p2: [-0.4, 24.0, -3.2], p3: [0.0, 15.0, -5.8], r0: 3.5, r1: 0.9 }
  ];

  const cfg = presets[idx];
  const p1 = [p0[0] + cfg.p1[0] + (api.random() - 0.5) * 0.4, p0[1] + cfg.p1[1], p0[2] + cfg.p1[2] + (api.random() - 0.5) * 0.4];
  const p2 = [p0[0] + cfg.p2[0] + (api.random() - 0.5) * 0.4, p0[1] + cfg.p2[1], p0[2] + cfg.p2[2] + (api.random() - 0.5) * 0.4];
  const p3 = [p0[0] + cfg.p3[0] + (api.random() - 0.5) * 0.4, p0[1] + cfg.p3[1], p0[2] + cfg.p3[2] + (api.random() - 0.5) * 0.4];

  // Palette assignment
  const darkScales = (idx % 3 === 0) ? "minecraft:dark_prismarine" : (idx % 3 === 1 ? "minecraft:warped_wart_block" : "minecraft:dark_prismarine");
  const midScales = (idx % 2 === 0) ? "minecraft:prismarine_bricks" : "minecraft:dark_prismarine";
  const bellySkin = (idx % 2 === 0) ? "minecraft:prismarine" : "minecraft:prismarine_bricks";
  const suckerGlowPool = [
    "minecraft:sea_lantern",
    "minecraft:pearlescent_froglight",
    "minecraft:ochre_froglight",
    "minecraft:crying_obsidian",
    "minecraft:shroomlight"
  ];
  const suckerGlow = suckerGlowPool[idx % suckerGlowPool.length];
  const suckerRim = (idx % 2 === 0) ? "minecraft:smooth_quartz" : "minecraft:bone_block";
  const spineWall = (idx % 3 === 0) ? "minecraft:prismarine_wall" : (idx % 3 === 1 ? "minecraft:deepslate_tile_wall" : "minecraft:blackstone_wall");

  const getRadius = (t) => {
    return cfg.r0 * Math.pow(1.0 - t, 0.72) + cfg.r1 * t + 0.32 * Math.sin(Math.PI * t);
  };

  const getFrame = (t) => {
    const C = bezier(p0, p1, p2, p3, t);
    const T = vNorm(bezierD1(p0, p1, p2, p3, t));
    const d2 = bezierD2(p0, p1, p2, p3, t);
    let Nraw = vSub(d2, vScale(T, vDot(d2, T)));
    if (vLen(Nraw) < 1e-4) {
      Nraw = vSub([0, 0, -1], vScale(T, vDot([0, 0, -1], T)));
    }
    if (vLen(Nraw) < 1e-4) {
      Nraw = vSub([1, 0, 0], vScale(T, vDot([1, 0, 0], T)));
    }
    const N = vNorm(Nraw);
    const B = vCross(T, N);
    return { C, T, N, B };
  };

  // 1. Rasterize main muscular trunk
  const steps = 140;
  for (let s = 0; s <= steps; s++) {
    const t = s / steps;
    const { C, T, N, B } = getFrame(t);
    const R = getRadius(t);

    const minX = Math.max(0, Math.floor(C[0] - R - 1));
    const maxX = Math.min(W - 1, Math.ceil(C[0] + R + 1));
    const minY = Math.max(0, Math.floor(C[1] - R - 1));
    const maxY = Math.min(H - 1, Math.ceil(C[1] + R + 1));
    const minZ = Math.max(0, Math.floor(C[2] - R - 1));
    const maxZ = Math.min(D - 1, Math.ceil(C[2] + R + 1));

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const Dvec = [x + 0.5 - C[0], y + 0.5 - C[1], z + 0.5 - C[2]];
          const distT = vDot(Dvec, T);
          if (Math.abs(distT) > 0.58) continue;

          const dN = vDot(Dvec, N); // Ventral is +N, Dorsal is -N
          const dB = vDot(Dvec, B); // Lateral width

          const rPerp = Math.sqrt(
            Math.pow(dN / (R * 0.94), 2) + Math.pow(dB / (R * 1.06), 2)
          );

          if (rPerp <= 1.0) {
            let block = midScales;
            if (rPerp < 0.45) {
              block = darkScales;
            } else if (dN > 0.22 * R) {
              block = bellySkin;
            } else if (dN < -0.22 * R) {
              block = darkScales;
            }
            setVoxel(x, y, z, block);
          }
        }
      }
    }
  }

  // 2. Ventral suckers with bio-luminescent cores
  const suckerCount = 14;
  for (let k = 0; k < suckerCount; k++) {
    const t = 0.12 + (k / (suckerCount - 1)) * 0.82;
    const { C, N, B } = getFrame(t);
    const R = getRadius(t);
    const isPaired = R > 1.25;
    const offsets = isPaired ? [-0.42 * R, 0.42 * R] : [0];

    for (const offset of offsets) {
      const sCenter = vAdd(
        vAdd(C, vScale(N, R * 0.94)),
        vScale(B, offset)
      );
      const sRad = isPaired ? 0.75 + 0.25 * (1 - t) : 0.65;

      const sx0 = Math.floor(sCenter[0] - sRad - 0.6);
      const sx1 = Math.ceil(sCenter[0] + sRad + 0.6);
      const sy0 = Math.floor(sCenter[1] - sRad - 0.6);
      const sy1 = Math.ceil(sCenter[1] + sRad + 0.6);
      const sz0 = Math.floor(sCenter[2] - sRad - 0.6);
      const sz1 = Math.ceil(sCenter[2] + sRad + 0.6);

      for (let x = sx0; x <= sx1; x++) {
        for (let y = sy0; y <= sy1; y++) {
          for (let z = sz0; z <= sz1; z++) {
            const d = vLen([x + 0.5 - sCenter[0], y + 0.5 - sCenter[1], z + 0.5 - sCenter[2]]);
            if (d <= sRad * 0.48) {
              setVoxel(x, y, z, suckerGlow);
            } else if (d <= sRad + 0.35) {
              setVoxel(x, y, z, suckerRim);
            }
          }
        }
      }
    }
  }

  // 3. Dorsal spines and barbed fins
  const spineCount = 11;
  for (let j = 0; j < spineCount; j++) {
    const t = 0.16 + (j / (spineCount - 1)) * 0.72;
    const { C, T, N } = getFrame(t);
    const R = getRadius(t);
    const spineDir = vNorm(vSub(vScale(N, -1.0), vScale(T, 0.35)));
    const spineLen = 1.2 + 1.6 * Math.sin(Math.PI * t);

    for (let l = 0; l <= spineLen; l += 0.5) {
      const sp = vAdd(vAdd(C, vScale(N, -R * 0.88)), vScale(spineDir, l));
      const b = (l >= spineLen - 0.6) ? spineWall : darkScales;
      setVoxel(Math.floor(sp[0]), Math.floor(sp[1]), Math.floor(sp[2]), b);
    }
  }

  // 4. Barnacle clusters along flanks
  const barnacleCount = 5;
  for (let b = 0; b < barnacleCount; b++) {
    const bt = 0.2 + (b / barnacleCount) * 0.6;
    const { C, N, B } = getFrame(bt);
    const R = getRadius(bt);
    const side = (b % 2 === 0) ? 1 : -1;
    const bPos = vAdd(vAdd(C, vScale(B, side * R * 0.92)), vScale(N, -0.2 * R));

    const bx = Math.floor(bPos[0]);
    const by = Math.floor(bPos[1]);
    const bz = Math.floor(bPos[2]);
    const bMat = (b % 2 === 0) ? "minecraft:calcite" : "minecraft:dead_brain_coral_block";
    setVoxel(bx, by, bz, bMat);
    setVoxel(bx + (side > 0 ? 1 : -1), by, bz, "minecraft:bone_block");
  }

  // 5. Muscular base roots and terrain conformance
  const rootCount = 5;
  for (let r = 0; r < rootCount; r++) {
    const angle = (r / rootCount) * Math.PI * 2 + (api.random() - 0.5) * 0.3;
    const rootLen = 2.4 + api.random() * 1.4;
    for (let d = 0; d <= rootLen; d += 0.5) {
      const rx = p0[0] + Math.cos(angle) * d;
      const rz = p0[2] + Math.sin(angle) * d;
      const ry = seatY + (1.0 - d / rootLen) * 1.5;
      const rootR = (1.0 - d / rootLen) * 1.4 + 0.5;

      for (let dx = -Math.ceil(rootR); dx <= Math.ceil(rootR); dx++) {
        for (let dz = -Math.ceil(rootR); dz <= Math.ceil(rootR); dz++) {
          if (dx * dx + dz * dz <= rootR * rootR) {
            setVoxel(Math.floor(rx + dx), Math.floor(ry), Math.floor(rz + dz), darkScales);
          }
        }
      }
    }
  }

  // Follow terrain down to seabed/foundation on every column
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let highestOccupied = -1;
      for (let y = seatY + 4; y >= 0; y--) {
        if (grid[x][y][z] !== null) {
          highestOccupied = y;
          break;
        }
      }

      if (highestOccupied >= 0) {
        const groundOffset = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(H - 1, seatY + groundOffset));

        if (groundY < seatY) {
          for (let y = seatY; y >= groundY; y--) {
            if (grid[x][y][z] === null) {
              const b = (y === groundY) ? "minecraft:cracked_stone_bricks" : darkScales;
              grid[x][y][z] = b;
            }
          }
        } else if (groundY > seatY) {
          for (let y = seatY; y <= groundY; y++) {
            if (grid[x][y][z] === null) {
              grid[x][y][z] = darkScales;
            }
          }
        }
      }
    }
  }

  // Sea spray & shattered stone collar around base waterline
  for (let x = 1; x < W - 1; x++) {
    for (let z = 1; z < D - 1; z++) {
      const gY = Math.max(0, Math.min(H - 2, seatY + api.heightAt(x, z)));
      if (grid[x][gY][z] === null) {
        const hasAdjacent = (
          (grid[x + 1][gY][z] !== null && grid[x + 1][gY][z] !== "minecraft:prismarine_wall") ||
          (grid[x - 1][gY][z] !== null && grid[x - 1][gY][z] !== "minecraft:prismarine_wall") ||
          (grid[x][gY][z + 1] !== null && grid[x][gY][z + 1] !== "minecraft:prismarine_wall") ||
          (grid[x][gY][z - 1] !== null && grid[x][gY][z - 1] !== "minecraft:prismarine_wall")
        );
        if (hasAdjacent && ((x + z + idx) % 3 === 0)) {
          grid[x][gY][z] = "minecraft:prismarine_wall";
        }
      }
    }
  }

  // Emit all voxels to the world API
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] !== null) {
          api.set(x, y, z, grid[x][y][z]);
        }
      }
    }
  }

  return {
    name: "Kraken Tentacle",
    seatY: seatY,
    anchors: {
      front: [Math.floor(p3[0]), Math.floor(p3[1]), 0],
      base: [Math.floor(p0[0]), seatY, Math.floor(p0[2])]
    }
  };
}
